// DEV_RIO_705 Threads×楽天。qa_status=PASS 時のみ楽天リプライを生成・自動投稿。
// DEV_RIO_103 の出力を受け取る。qa_status が無い手動テスト時は 'PASS' 扱い。
const i = $input.first().json;
return [{ json: {
  content_id: i.content_id ?? 'ca-threads-aff-001',
  threads_post: i.threads_post ?? '',
  qa_status: i.qa_status ?? 'PASS',
  platform: 'threads',
  action_type: 'post_rakuten_reply'
} }];

// ============================================================
// 楽天アフィリエイト リンクライブラリ（定数）
// ============================================================
// マスターは products/revenue-intelligence-os/data/rakuten_link_library.csv。
// n8nクラウドはローカルファイルを読めないため、CSVの status=active の行を
// この LINK_LIBRARY 定数へ手で転記して運用する（CSVがマスター、ここは写し）。
// 転記手順: CSVに行追加 → 下の配列に同内容を追加 → Save → 手動テスト実行。
// ⚠ affiliate_url はゆうさんが楽天アフィリ管理画面で発行した実URLのみ。
//   手打ち・推測・生成したURLをここに書くことは禁止（リンク捏造ゼロ）。
// 記入例（ダミー・コメントのみ。実URLではない）:
// { id: 'RKT-001', genre: 'kitchen', aliases: ['キッチン', '調理器具'],
//   product_name: '（例）フライパン28cm',
//   affiliate_url: 'https://hb.afl.rakuten.co.jp/hgc/XXXXXXXX/?pc=DUMMY-DO-NOT-USE',
//   pr_note: '楽天アフィリエイトリンクを含みます', status: 'active' }
const LINK_LIBRARY = [
  // CSV（rakuten_link_library.csv）からの転記。2026-08-02 発行分。
  { id: 'RKT-001', genre: 'photo_gear', aliases: ['撮影機材', 'リングライト', 'スマホ撮影', 'ライト', '写真', 'photo', 'lighting'],
    product_name: 'リングライト 三脚タイプ スマホスタンド 10インチ',
    affiliate_url: 'https://a.r10.to/hkmJqO',
    pr_note: '楽天アフィリエイトリンクを含みます', status: 'active' },
  { id: 'RKT-002', genre: 'store_signage', aliases: ['看板', 'A型看板', 'ブラックボード', '店頭看板', '黒板', 'signage'],
    product_name: 'A型看板 ブラックボード 両面 38×78cm 木製',
    affiliate_url: 'https://a.r10.to/T3YbFn',
    pr_note: '楽天アフィリエイトリンクを含みます', status: 'active' },
  { id: 'RKT-003', genre: 'marketing_book', aliases: ['集客本', 'マーケティング本', '書籍', '本', 'book', 'sns集客'],
    product_name: '店舗やサロンのためのInstagram集客・販促の教科書',
    affiliate_url: 'https://a.r10.to/hgtsW1',
    pr_note: '楽天アフィリエイトリンクを含みます', status: 'active' }
];
const active = LINK_LIBRARY.filter(e => e && e.status === 'active' && e.affiliate_url);
const genre_keys = [...new Set(active.map(e => String(e.genre || '').trim()).filter(Boolean))];
const i = $input.first().json;
return [{ json: { ...i, link_library: active, genre_keys } }];

// 楽天リプライ下書きの生成プロンプトを Anthropic body オブジェクトとして組み立てる。
// product_genre はリンクライブラリのジャンルキーから選ばせ、後段の照合を確実にする。
const i = $input.first().json;
const post = String(i.threads_post || '').slice(0, 300);
const genres = (i.genre_keys && i.genre_keys.length) ? i.genre_keys.join(' / ') : '(登録なし)';
const prompt = `以下のThreads投稿に自然に続く、商品紹介リプライの下書きを2案。\n\n投稿: ${post}\n\n条件:\n- 各60字以内、日本語。\n- 押し売り感なし。\n- 実在商品を断定しない。特定の商品名・URLは書かない。\n- product_genre は次のジャンルキーから最も合うものを1つだけ選ぶ: ${genres}。どれも合わない場合は "none" とする。\n- 出力は次のJSON配列のみ（前後に説明・コードブロック記号を付けない）:\n[{"reply":"string","product_genre":"string"}]`;
const anthropic_body = {
  model: 'claude-haiku-4-5',
  max_tokens: 512,
  messages: [ { role: 'user', content: prompt } ]
};
return [{ json: { ...i, anthropic_body } }];

// Claude応答をパース。捏造しない。リンクは後段の Match Rakuten Link でのみ付与される。
const input = $input.first().json;
const ctx = $('Collect Inputs').first().json;
let replies = [];
let parse_error = null;
if (input.error) {
  parse_error = 'anthropic_api_error: ' + JSON.stringify(input.error).slice(0, 300);
} else {
  try {
    const text = input.content && input.content[0] && input.content[0].text;
    if (!text) throw new Error('no text in response');
    const cleaned = text.trim().replace(/^```json\s*/i, '').replace(/```\s*$/, '');
    const match = cleaned.match(/\[[\s\S]*\]/);
    replies = JSON.parse(match ? match[0] : cleaned);
    if (!Array.isArray(replies) || replies.length === 0) throw new Error('replies missing/empty');
  } catch (e) {
    parse_error = 'parse_failed: ' + e.message;
  }
}
if (parse_error) replies = [{ reply: '（AI応答の取得/解析に失敗。手動で作成してください）', product_genre: 'manual' }];
const enriched = replies.map((r) => ({
  content_id: ctx.content_id,
  reply: r.reply ?? '',
  product_genre: r.product_genre ?? '',
  draft_error: parse_error
}));
return enriched.map(item => ({ json: item }));

// リンクライブラリ照合。ゆうさん発行の実リンクがある genre の下書きだけ投稿対象にする。
// マッチしない下書きは link_matched=false → 後段の Link Gate で NO_LINK_SKIP へ。
// これにより「リンクなし・プレースホルダーのままの投稿」は構造的に発生しない。
const lib = $('Link Library').first().json.link_library || [];
const norm = (s) => String(s || '').trim().toLowerCase();
const items = $input.all();
return items.map((item) => {
  const d = item.json;
  const g = norm(d.product_genre);
  let entry = null;
  if (g && g !== 'none' && g !== 'manual') {
    entry = lib.find(e => norm(e.genre) === g || (Array.isArray(e.aliases) && e.aliases.some(a => norm(a) === g))) || null;
  }
  if (!entry) {
    return { json: { ...d, link_matched: false } };
  }
  // 投稿文には必ず【PR】表記を含める（ステマ規制対応）。リンクはライブラリの実URLのみ。
  const pr_line = '【PR】' + (entry.pr_note ? String(entry.pr_note) : '楽天アフィリエイトリンクを含みます');
  const final_reply = [String(d.reply || ''), '', pr_line, String(entry.affiliate_url)].join('\n');
  // Threads API へは改行・記号入りテキストをクエリではなく JSON body で送る（400 Bad request 対策）。
  // Anthropic 呼び出しと同じ「Code ノードで body を組み立てて jsonBody で渡す」パターン。
  const threads_body = { media_type: 'TEXT', text: final_reply };
  return { json: {
    ...d,
    link_matched: true,
    link_id: entry.id ?? null,
    product_name: entry.product_name ?? null,
    affiliate_url: entry.affiliate_url,
    final_reply,
    threads_body
  } };
});

// Publish 用の body を組み立てる（creation_id もクエリではなく JSON body で送る堅牢化）。
// コンテナ作成が失敗した item は id が無く creation_id='' となり、Publish が失敗して
// Aggregate Results で POST_FAILED として集計される（従来と同じ挙動）。
const items = $input.all();
return items.map((item) => {
  const j = item.json;
  return { json: { ...j, publish_body: { creation_id: String(j.id || '') } } };
});

// Threads API 応答を集約。
const items = $input.all();
const ctx = $('Collect Inputs').first().json;
const results = items.map((item, idx) => {
  const publish = item.json;
  const posted = !!(publish && publish.id && !publish.error);
  return {
    content_id: ctx.content_id,
    thread_id: posted ? publish.id : null,
    state: posted ? 'POSTED' : 'POST_FAILED',
    published: posted,
    posted_at: posted ? new Date().toISOString() : null,
    error: publish && publish.error ? JSON.stringify(publish.error).slice(0, 300) : null
  };
});
return [{ json: { results, posted_count: results.filter(r => r.published).length, failed_count: results.filter(r => !r.published).length } }];

// リンクライブラリに該当 genre の active リンクが無いため、この下書きは投稿しない。
// リンクなし・プレースホルダーのままの投稿を出さないための恒久ガード。
const items = $input.all();
const results = items.map((item) => ({
  content_id: item.json.content_id,
  reply: item.json.reply,
  product_genre: item.json.product_genre,
  state: 'NO_LINK_SKIP',
  published: false,
  note: 'ライブラリに genre 一致の active リンクが無いためスキップ。rakuten_link_library.csv に登録し Link Library ノードへ転記すれば投稿対象になる。'
}));
return [{ json: { state: 'NO_LINK_SKIP', skipped_count: results.length, results } }];

// QAゲート不通過。リプライ生成をスキップ。
const i = $input.first().json;
return [{ json: {
  content_id: i.content_id,
  skipped: true,
  qa_status: i.qa_status,
  state: 'SKIPPED_NOT_PASS',
  published: false,
  note: 'qa_status が PASS ではないため Threads楽天リプライ生成をスキップ。'
} }];
